scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    count = 0
    n = len(values)

    # Check all pairs (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.luhn_checksum:
def solve(inputs: dict) -> float:
    n = str(inputs['N'])
    digits = [int(d) for d in n]

    # Process from right to left
    total = 0
    for i in range(len(digits) - 1, -1, -1):
        # Position from the right (1-indexed)
        pos_from_right = len(digits) - i

        digit = digits[i]

        # Double every second digit (even positions from the right)
        if pos_from_right % 2 == 0:
            digit = digit * 2
            if digit > 9:
                digit = digit - 9

        total += digit

    return float(total)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    x = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    # Apply the recurrence k times
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

scripts.sum_integer_quotients:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = 0
    for a, b in zip(A, B):
        quotient = a // b  # integer division
        total += quotient

    return float(total)

